//! The client <-> host wire contract: MessagePack frames over one WebSocket. TypeScript bindings
//! are generated by ts-rs into packages/core/src/contract/ (`cargo test -p steerd`).

use serde::{Deserialize, Serialize};
use steer_demos::{DemoInfo, FrameView};
use ts_rs::TS;

/// A call from the client, tagged as `{ method, params }`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(tag = "method", content = "params")]
#[ts(export)]
pub enum Call {
    #[serde(rename = "demo.list")]
    DemoList,
}

/// Client -> host.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct Request {
    pub id: u32,
    pub call: Call,
}

/// The answer to a call, tagged as `{ type, value }`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, TS)]
#[serde(tag = "type", content = "value", rename_all = "snake_case")]
#[ts(export)]
pub enum Reply {
    Demos(Vec<DemoInfo>),
}

/// Host -> client. Tagged as `{ t, ... }`.
#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[serde(tag = "t", rename_all = "snake_case")]
#[ts(export)]
pub enum HostFrame {
    Res {
        id: u32,
        result: Option<Reply>,
        error: Option<String>,
    },
    /// The world after one simulation step, sent to every client.
    Frame { frame: FrameView },
}
